 <script>
 document.addEventListener('DOMContentLoaded', function () {
 document.querySelectorAll('select[data-clearable-filter]').forEach(function (select, index) {
 if (!Array.from(select.options).some(function (option) { return option.hasAttribute('selected'); })) {
 select.selectedIndex = -1;
 }
 const defaults = {
 status: 'All Status', application_status: 'All Status', notice_status: 'All Status',
 channel: 'All Methods', payment_type: 'All Types', type: 'All Types',
 category: 'All Categories', month: 'All Months', year: 'All Years',
 membership: 'All Memberships', notice_membership: 'All Memberships'
 };
 const label = select.dataset.filterDefault || defaults[select.name];
 if (!label) return;
 const value = document.createElement('span');
 value.className = 'status-filter-value';
 value.id = 'filter-default-' + index;
 value.textContent = label;
 value.style.fontSize = window.getComputedStyle(select).fontSize;
 select.parentElement.classList.add('status-filter-display');
 select.insertAdjacentElement('afterend', value);
 const update = function () {
 const empty = select.selectedIndex < 0;
 value.hidden = !empty;
 if (empty) select.setAttribute('aria-describedby', value.id);
 else select.removeAttribute('aria-describedby');
 };
 select.addEventListener('change', update);
 update();
 });
 document.querySelectorAll('form[data-auto-filter]').forEach(function (form) {
 let timer = null;

 const clearTimer = function () {
 if (timer !== null) {
 window.clearTimeout(timer);
 timer = null;
 }
 };

 const submit = function () {
 clearTimer();

 if (typeof form.requestSubmit === 'function') {
 form.requestSubmit();
 } else {
 form.submit();
 }
 };

 const scheduleSubmit = function () {
 clearTimer();

 const configuredDelay = Number(form.dataset.autoFilterDebounce);
 const delay = Number.isFinite(configuredDelay) && configuredDelay >= 0
 ? configuredDelay
 : 450;

 timer = window.setTimeout(submit, delay);
 };

 form.querySelectorAll('select, input[type="month"], input[type="date"], input[type="week"], input[type="time"], input[type="checkbox"], input[type="radio"]').forEach(function (control) {
 control.addEventListener('change', submit);
 });

 form.querySelectorAll('input[type="search"], input[type="text"]').forEach(function (input) {
 input.addEventListener('input', scheduleSubmit);
 input.addEventListener('keydown', function (event) {
 if (event.key === 'Enter') {
 event.preventDefault();
 submit();
 }
 });
 });

 form.addEventListener('submit', clearTimer);
 form.addEventListener('period-picker-open', clearTimer);

 form.querySelectorAll('a').forEach(function (link) {
 link.addEventListener('click', clearTimer);
 });

 document.addEventListener('click', function (event) {
 if (!form.contains(event.target)) {
 clearTimer();
 }
 }, true);

 window.addEventListener('pagehide', clearTimer);
 });
 });
 </script>
 <script>
 document.addEventListener('DOMContentLoaded', function () {
 const appShell = document.querySelector('.app-shell');
 const sidebar = document.getElementById('sidebarMenu');
 const collapseToggle = document.getElementById('sidebarCollapseToggle');
 const mobileToggle = document.getElementById('sidebarMobileToggle');
 const backdrop = document.getElementById('sidebarBackdrop');
 const mainContent = document.querySelector('.main-content');

 if (!appShell || !sidebar) {
 return;
 }

 const mobileQuery = window.matchMedia('(max-width: 991.98px)');
 const toggles = [collapseToggle, mobileToggle].filter(Boolean);

 const isMobile = function () {
 return mobileQuery.matches;
 };

 const isSidebarOpen = function () {
 return isMobile()
 ? appShell.classList.contains('sidebar-mobile-open')
 : !appShell.classList.contains('sidebar-collapsed');
 };

 const syncState = function () {
 const open = isSidebarOpen();

 toggles.forEach(function (toggle) {
 toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
 });

 if (collapseToggle) {
 const label = open ? 'Collapse sidebar' : 'Open sidebar';

 collapseToggle.setAttribute('aria-label', label);
 collapseToggle.setAttribute('title', label);
 }

 if (mobileToggle) {
 const label = open ? 'Close sidebar' : 'Open sidebar';

 mobileToggle.setAttribute('aria-label', label);
 mobileToggle.setAttribute('title', label);
 }

 sidebar.toggleAttribute('inert', isMobile() && !open);

 if (mainContent) {
 mainContent.toggleAttribute('inert', isMobile() && open);
 }
 };

 const openSidebar = function () {
 if (isMobile()) {
 appShell.classList.add('sidebar-mobile-open');
 } else {
 appShell.classList.remove('sidebar-collapsed');
 }

 syncState();

 const firstLink = sidebar.querySelector('.nav-link:not(.sidebar-subnav-link)')
 || sidebar.querySelector('.nav-link');

 if (isMobile() && firstLink) {
 window.setTimeout(function () {
 firstLink.focus();
 }, 0);
 }
 };

 const closeSidebar = function () {
 if (isMobile()) {
 appShell.classList.remove('sidebar-mobile-open');
 } else {
 appShell.classList.add('sidebar-collapsed');
 }

 syncState();

 const focusTarget = isMobile() && mobileToggle ? mobileToggle : collapseToggle;

 if (focusTarget) {
 window.setTimeout(function () {
 focusTarget.focus();
 }, 0);
 }
 };

 const toggleSidebar = function () {
 if (isSidebarOpen()) {
 closeSidebar();
 } else {
 openSidebar();
 }
 };

 toggles.forEach(function (toggle) {
 toggle.addEventListener('click', toggleSidebar);
 });

 sidebar.querySelectorAll('.sidebar-submenu-toggle').forEach(function (toggle) {
 toggle.addEventListener('click', function (event) {
 if (!isMobile() && appShell.classList.contains('sidebar-collapsed')) {
 const submenu = document.getElementById(toggle.getAttribute('aria-controls'));
 openSidebar();
 // An already-open submenu becomes visible as the rail expands.
 if (submenu && submenu.classList.contains('show')) event.stopPropagation();
 }
 });
 });

 if (backdrop) {
 backdrop.addEventListener('click', closeSidebar);
 }

 document.addEventListener('keydown', function (event) {
 if (event.key === 'Escape' && isMobile() && isSidebarOpen()) {
 closeSidebar();
 }
 });

 const handleBreakpointChange = function () {
 appShell.classList.remove('sidebar-mobile-open', 'sidebar-collapsed');
 syncState();
 };

 if (typeof mobileQuery.addEventListener === 'function') {
 mobileQuery.addEventListener('change', handleBreakpointChange);
 } else if (typeof mobileQuery.addListener === 'function') {
 mobileQuery.addListener(handleBreakpointChange);
 }

 syncState();
 });
 </script>
 <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
 <script>
 document.addEventListener('DOMContentLoaded', function () {
 const chartData = {"has_data":true,"area_totals":{"labels":["Purok 2-B / Block not recorded","Purok 1-C / Block 4","Purok 1-C / Block 5","Purok 2-A / Block not recorded","Purok not recorded / Block 7","Location not specified","Purok 1-A / Block 2"],"counts":[1,1,1,1,1,1,0]},"area_priority":{"labels":["Purok 1-C / Block 4","Location not specified","Purok 1-C / Block 5","Purok 2-A / Block not recorded","Purok 2-B / Block not recorded","Purok not recorded / Block 7"],"open":[1,1,1,1,1,1]},"area_categories":{"labels":["Purok 2-B / Block not recorded","Purok 1-C / Block 4","Purok 1-C / Block 5","Purok 2-A / Block not recorded","Purok not recorded / Block 7","Location not specified","Purok 1-A / Block 2"],"datasets":[{"label":"Meter Concern","data":[1,0,0,0,0,0,1]},{"label":"No Water Supply","data":[0,0,0,1,0,1,0]},{"label":"Water Leak","data":[0,2,0,0,1,0,0]},{"label":"Water Quality Issue","data":[0,0,1,0,0,0,0]}]},"hotspots":{"labels":["Purok 2-B / Block not recorded","Purok 1-C / Block 4","Purok 1-C / Block 5","Purok 2-A / Block not recorded","Purok not recorded / Block 7","Location not specified","Purok 1-A / Block 2"],"open":[1,1,1,1,1,1,0],"resolved":[0,1,0,0,0,0,1]},"categories":{"labels":["Meter Concern","No Water Supply","Water Leak","Water Quality Issue"],"counts":[2,2,3,1]},"statuses":{"labels":["Pending","Resolved"],"counts":[6,2]},"trend":{"labels":["Sep 2026","Oct 2026"],"reported":[1,7],"resolved":[0,2],"has_data":true,"direction":"Increasing","latest_month_delta":6}};
 const chartColors = ['#0f7890', '#56a7b5', '#e3a83b', '#d85b55', '#7b70b8', '#55a5c0', '#7d9c70', '#9a7a61'];
 const areaTotalsCanvas = document.getElementById('incidentAreaTotalsChart');

 if (areaTotalsCanvas) {
 new Chart(areaTotalsCanvas, {
 type: 'bar',
 data: {
 labels: chartData.area_totals.labels,
 datasets: [{
 label: 'Unresolved reports',
 data: chartData.area_totals.counts,
 backgroundColor: chartColors[0],
 borderRadius: 4,
 }]
 },
 options: {
 indexAxis: 'y',
 responsive: true,
 maintainAspectRatio: false,
 scales: { x: { beginAtZero: true, ticks: { precision: 0 } } },
 plugins: { legend: { display: false } }
 }
 });
 }

 const areaPriorityCanvas = document.getElementById('incidentAreaPriorityChart');

 if (areaPriorityCanvas) {
 new Chart(areaPriorityCanvas, {
 type: 'bar',
 data: {
 labels: chartData.area_priority.labels,
 datasets: [{
 label: 'Unresolved incidents (priority proxy)',
 data: chartData.area_priority.open,
 backgroundColor: '#e3a83b',
 borderRadius: 4,
 }]
 },
 options: {
 indexAxis: 'y',
 responsive: true,
 maintainAspectRatio: false,
 scales: { x: { beginAtZero: true, ticks: { precision: 0 } } },
 plugins: { legend: { position: 'bottom', labels: { boxWidth: 12, usePointStyle: true } } }
 }
 });
 }

 const areaCategoriesCanvas = document.getElementById('incidentAreaCategoriesChart');

 if (areaCategoriesCanvas) {
 new Chart(areaCategoriesCanvas, {
 type: 'bar',
 data: {
 labels: chartData.area_categories.labels,
 datasets: chartData.area_categories.datasets.map((dataset, index) => ({
 ...dataset,
 backgroundColor: chartColors[index % chartColors.length],
 borderRadius: 3,
 }))
 },
 options: {
 indexAxis: 'y',
 responsive: true,
 maintainAspectRatio: false,
 scales: {
 x: { stacked: true, beginAtZero: true, ticks: { precision: 0 } },
 y: { stacked: true }
 },
 plugins: { legend: { position: 'bottom', labels: { boxWidth: 12, usePointStyle: true } } }
 }
 });
 }

 const trendCanvas = document.getElementById('incidentTrendChart');

 if (trendCanvas) {
 new Chart(trendCanvas, {
 type: 'line',
 data: {
 labels: chartData.trend.labels,
 datasets: [
 {
 label: 'Reported',
 data: chartData.trend.reported,
 borderColor: '#0d6efd',
 backgroundColor: 'rgba(13, 110, 253, .12)',
 fill: true,
 tension: .35,
 pointRadius: 3,
 },
 {
 label: 'Resolved (same reporting month)',
 data: chartData.trend.resolved,
 borderColor: '#20c997',
 backgroundColor: 'rgba(32, 201, 151, .12)',
 fill: false,
 tension: .35,
 pointRadius: 3,
 }
 ]
 },
 options: {
 responsive: true,
 maintainAspectRatio: false,
 interaction: { mode: 'index', intersect: false },
 scales: {
 y: { beginAtZero: true, ticks: { precision: 0 } }
 },
 plugins: {
 legend: { position: 'bottom', labels: { boxWidth: 12, usePointStyle: true } }
 }
 }
 });
 }

 });
 </script>
 <script>
 document.addEventListener('DOMContentLoaded', function () {
 const main = document.querySelector('.main-content');
 const content = main?.querySelector('.content-wrapper');
 if (!content) return;
 if (content.querySelector('[data-admin-natural-page-scroll]')) return;
 main.style.setProperty('--admin-window-gutter', (window.innerWidth - document.documentElement.clientWidth) + 'px');

 const consumerPage = content.querySelector('[data-admin-page-scroll]');
 const first = content.querySelector('[data-admin-records-root]')
 || [...content.children].find(element => !element.matches('.page-heading, .modal, script, style'));
 if (!first) return;
 if (consumerPage) {
 main.classList.add('admin-scroll-shell');
 document.documentElement.classList.add('admin-consumer-page-scroll');
 const topbar = main.querySelector('.topbar');
 const setTopbarHeight = function () {
 main.style.setProperty('--consumer-topbar-height', topbar.getBoundingClientRect().height + 'px');
 };
 setTopbarHeight();
 new ResizeObserver(setTopbarHeight).observe(topbar);
 }
 const sectionScroll = first.hasAttribute('data-admin-section-scroll') || Boolean(consumerPage);

 const parent = first.parentElement;
 const margins = window.getComputedStyle(first);
 const area = document.createElement('div');
 area.className = 'admin-records-area';
 area.setAttribute('role', 'region');
 area.setAttribute('aria-label', 'Admin records and page content');
 area.tabIndex = 0;
 ['Top', 'Left', 'Right'].forEach(function (side) {
 const value = margins['margin' + side];
 first.style.setProperty('--admin-original-' + side.toLowerCase(), value);
 if (side === 'Top' && parseFloat(value) < 0) {
 first.style.setProperty('--admin-first-top', value);
 area.style.marginTop = '0px';
 } else {
 area.style['margin' + side] = value;
 }
 });
 area.style.setProperty('--admin-area-original-left', margins.marginLeft);
 area.style.setProperty('--admin-area-original-right', margins.marginRight);
 parent.insertBefore(area, first);
 while (area.nextSibling) area.appendChild(area.nextSibling);
 [...area.children].filter(element => !element.matches('.modal, script, style')).forEach(function (element) {
 const styles = window.getComputedStyle(element);
 element.style.setProperty('--admin-item-original-left', styles.marginLeft);
 element.style.setProperty('--admin-item-original-right', styles.marginRight);
 element.classList.add('admin-area-item');
 });
 first.classList.add('admin-area-first');

 for (let ancestor = parent; ancestor && ancestor !== main; ancestor = ancestor.parentElement) {
 ancestor.style.setProperty('--admin-path-display', window.getComputedStyle(ancestor).display);
 ancestor.classList.add('admin-scroll-path');
 }
 main.classList.add('admin-scroll-shell');
 document.documentElement.classList.add('admin-one-scroll');

 const tableHeadings = [];
 area.querySelectorAll('table').forEach(function (table) {
 if (table.closest('.modal')) return;
 table.closest('.panel-card, .billing-card')?.classList.add('admin-records-surface');
 if (table.tHead) {
 table.tHead.classList.add('admin-table-heading');
 if (! (consumerPage && table.closest('#active-disconnection-notices'))) tableHeadings.push(table.tHead);
 }
 const wrapper = table.parentElement;
 const styles = window.getComputedStyle(wrapper);
 if (['auto', 'scroll'].includes(styles.overflowX) || ['auto', 'scroll'].includes(styles.overflowY)) {
 if (wrapper.scrollHeight > wrapper.clientHeight + 1) wrapper.style.scrollbarGutter = 'stable';
 wrapper.classList.add('admin-natural-records', 'admin-table-viewport');
 wrapper.style.removeProperty('max-height');
 wrapper.style.removeProperty('height');
 }
 });
 area.querySelectorAll('*').forEach(function (element) {
 if (element.matches('textarea, select') || element.closest('.modal, .dropdown-menu')) return;
 const styles = window.getComputedStyle(element);
 if (['auto', 'scroll'].includes(styles.overflowY) && styles.maxHeight !== 'none') {
 element.classList.add('admin-natural-records');
 }
 });

 const frozen = [...area.querySelectorAll('[data-admin-freeze]')];
 const recordParts = [];
 const collectRecords = function (element) {
 if (element.matches('[data-admin-freeze], .modal, script, style')) return;
 if (element.querySelector('[data-admin-freeze], .modal')) {
 [...element.children].forEach(collectRecords);
 } else {
 element.classList.add('admin-record-part');
 recordParts.push(element);
 }
 };
 [...area.children].forEach(collectRecords);
 frozen.forEach(function (element) {
 for (let ancestor = element.parentElement; ancestor && ancestor !== area; ancestor = ancestor.parentElement) {
 const styles = window.getComputedStyle(ancestor);
 if (['auto', 'scroll', 'hidden', 'clip'].includes(styles.overflowY)
 || ['auto', 'scroll', 'hidden', 'clip'].includes(styles.overflowX)) ancestor.style.overflow = 'visible';
 }
 });

 let frame = null;
 let paintFrame = null;
 const paintRecords = function () {
 paintFrame = null;
 if (main.classList.contains('admin-content-scroll')) return;
 const areaTop = area.getBoundingClientRect().top;
 if (consumerPage) {
 const activeTitle = area.querySelector('#active-accounts > .consumer-section-controls');
 const activeFilters = area.querySelector('#account-filters');
 if (activeTitle) activeTitle.style.setProperty('--admin-freeze-top', '0px');
 if (activeTitle && activeFilters) activeFilters.style.setProperty('--admin-freeze-top', activeTitle.getBoundingClientRect().height + 'px');
 }
 const primary = frozen.filter(element => element.classList.contains('admin-primary-freeze'));
 primary.forEach(element => element.style.setProperty('--admin-extra-shift', '0px'));
 const offsets = primary.map(element => Math.max(0,
 areaTop + parseFloat(element.style.getPropertyValue('--admin-freeze-top')) - element.getBoundingClientRect().top));
 primary.forEach((element, index) => element.style.setProperty('--admin-extra-shift', offsets[index] + 'px'));
 const headers = frozen.map(element => ({ element, box: element.getBoundingClientRect(),
 margin: parseFloat(window.getComputedStyle(element).marginBottom) || 0 }))
 .filter(({ box }) => box.height > 0 && box.bottom > areaTop);
 const visibleBottom = headers.filter(({ element, box }) => Math.abs(box.top - areaTop
